package com.mobileai.assistant.domain.artifact

import kotlinx.serialization.Serializable
import java.util.UUID

/**
 * Supported artifact formats generated by Dots in the workspace.
 */
enum class ArtifactType {
    MARKDOWN,
    CODE,
    JSON,
    CSV,
    SVG,
    DIAGRAM,
    TEXT
}

/**
 * Historical snapshot representing an immutable version revision of an artifact.
 */
@Serializable
data class ArtifactVersion(
    val id: String = UUID.randomUUID().toString(),
    val artifactId: String,
    val version: Int,
    val content: String,
    val changeSummary: String? = null,
    val timestamp: Long = System.currentTimeMillis()
)

/**
 * Persistent document or code artifact created and evolved by a Dot.
 */
@Serializable
data class WorkspaceArtifact(
    val id: String = UUID.randomUUID().toString(),
    val dotId: String,
    val conversationId: String,
    val taskId: String? = null,
    val stepId: String? = null,
    val title: String,
    val type: ArtifactType,
    val language: String? = null, // e.g., "kotlin", "json", "python"
    val content: String,
    val version: Int = 1,
    val filePath: String? = null,
    val createdAt: Long = System.currentTimeMillis(),
    val updatedAt: Long = System.currentTimeMillis()
)
